void WifiStation::StartFullScan() {
    const auto error = esp_wifi_scan_start(nullptr, false);
    if (error != ESP_OK) {
        ESP_LOGW(TAG, "SCAN_START_FAILED code=%d", int(error));
        esp_timer_start_once(timer_handle_, scan_current_interval_microseconds_);
        UpdateScanInterval();
    }
}

void WifiStation::HandleScanDone(bool success) {
    if (!success) {
        // A failed scan is not evidence of an empty radio environment.
        connect_queue_.clear();
        esp_wifi_clear_ap_list();
        ESP_LOGW(TAG, "SCAN_COMPLETION_FAILED");
        esp_timer_start_once(timer_handle_, scan_current_interval_microseconds_);
        UpdateScanInterval();
        return;
    }
    HandleScanResult();
}

