void WifiStation::StartConnect() {
    auto ap_record = connect_queue_.front();
    connect_queue_.erase(connect_queue_.begin());
    ssid_ = ap_record.ssid;
    password_ = ap_record.password;

    if (on_connect_) {
        on_connect_(ssid_);
    }

    wifi_config_t wifi_config;
    bzero(&wifi_config, sizeof(wifi_config));
    size_t ssid_len = ap_record.ssid.size();
    if (ssid_len > sizeof(wifi_config.sta.ssid)) {
        ssid_len = sizeof(wifi_config.sta.ssid);
    }
    memcpy(wifi_config.sta.ssid, ap_record.ssid.data(), ssid_len);

    size_t password_len = ap_record.password.size();
    if (password_len > sizeof(wifi_config.sta.password)) {
        password_len = sizeof(wifi_config.sta.password);
    }
    memcpy(wifi_config.sta.password, ap_record.password.data(), password_len);

    if (ap_record.channel != 0) {
        // We just found this AP; start on its channel instead of scanning all.
        wifi_config.sta.channel = ap_record.channel;
    }

    if (remember_bssid_) {
        // Explicit opt-in: pin to this exact AP (BSSID + channel) for the fastest
        // reconnect. This intentionally disables roaming between same-SSID APs.
        memcpy(wifi_config.sta.bssid, ap_record.bssid, 6);
        wifi_config.sta.bssid_set = true;
    } else if (ap_record.channel == 0) {
        // Channel unknown: ask the driver to scan every channel and connect to
        // the same-SSID AP with the strongest signal.
        wifi_config.sta.scan_method = WIFI_ALL_CHANNEL_SCAN;
        wifi_config.sta.sort_method = WIFI_CONNECT_AP_BY_SIGNAL;
        wifi_config.sta.failure_retry_cnt = ap_record.direct ? 0 : failure_retry_cnt_;
    } else {
        // Channel is already known from our scan. Use a fast scan on that
        // channel so connect does not walk the whole band again.
        wifi_config.sta.scan_method = WIFI_FAST_SCAN;
        wifi_config.sta.sort_method = WIFI_CONNECT_AP_BY_SIGNAL;
        wifi_config.sta.failure_retry_cnt = failure_retry_cnt_;
    }
    wifi_config.sta.listen_interval = 10;
    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wifi_config));

    // One driver attempt per fallback candidate; retain ordinary visible-AP
    // retry behavior. Failed candidates progress to the next, then back off.
    reconnect_count_ = ap_record.direct ? MAX_RECONNECT_COUNT : 0;
    const auto connect_error = esp_wifi_connect();
    if (ap_record.direct && connect_error != ESP_OK) {
        ESP_LOGW(TAG, "SAVED_DIRECT_START_FAILED code=%d", int(connect_error));
        if (!connect_queue_.empty()) {
            StartConnect(); // Bounded by the three-entry fallback queue.
        } else {
            esp_timer_start_once(timer_handle_, scan_current_interval_microseconds_);
            UpdateScanInterval();
        }
        return;
    }
    ESP_ERROR_CHECK(connect_error);
}
void WifiStation::StartConnect() {
    // Consume this finite queue iteratively. Synchronous driver failures must
    // not abort firmware or recurse once per visible BSSID.
    while (!connect_queue_.empty()) {
        auto ap_record = std::move(connect_queue_.front());
        connect_queue_.erase(connect_queue_.begin());
        ssid_ = ap_record.ssid;
        password_ = ap_record.password;

        if (on_connect_) {
            on_connect_(ssid_);
        }

        wifi_config_t wifi_config;
        bzero(&wifi_config, sizeof(wifi_config));
        size_t ssid_len = ap_record.ssid.size();
        if (ssid_len > sizeof(wifi_config.sta.ssid)) {
            ssid_len = sizeof(wifi_config.sta.ssid);
        }
        memcpy(wifi_config.sta.ssid, ap_record.ssid.data(), ssid_len);

        size_t password_len = ap_record.password.size();
        if (password_len > sizeof(wifi_config.sta.password)) {
            password_len = sizeof(wifi_config.sta.password);
        }
        memcpy(wifi_config.sta.password, ap_record.password.data(), password_len);

        if (ap_record.channel != 0) {
            // We just found this AP; start on its channel instead of scanning all.
            wifi_config.sta.channel = ap_record.channel;
        }

        if (remember_bssid_) {
            // Explicit opt-in: pin to this exact AP (BSSID + channel) for the fastest
            // reconnect. This intentionally disables roaming between same-SSID APs.
            memcpy(wifi_config.sta.bssid, ap_record.bssid, 6);
            wifi_config.sta.bssid_set = true;
        } else if (ap_record.channel == 0) {
            // Channel unknown: ask the driver to scan every channel and connect to
            // the same-SSID AP with the strongest signal.
            wifi_config.sta.scan_method = WIFI_ALL_CHANNEL_SCAN;
            wifi_config.sta.sort_method = WIFI_CONNECT_AP_BY_SIGNAL;
            wifi_config.sta.failure_retry_cnt = ap_record.direct ? 0 : failure_retry_cnt_;
        } else {
            // Channel is already known from our scan. Use a fast scan on that
            // channel so connect does not walk the whole band again.
            wifi_config.sta.scan_method = WIFI_FAST_SCAN;
            wifi_config.sta.sort_method = WIFI_CONNECT_AP_BY_SIGNAL;
            wifi_config.sta.failure_retry_cnt = failure_retry_cnt_;
        }
        wifi_config.sta.listen_interval = 10;
        const auto config_error = esp_wifi_set_config(WIFI_IF_STA, &wifi_config);
        if (config_error != ESP_OK) {
            ESP_LOGW(TAG, "CONNECT_CONFIG_FAILED code=%d", int(config_error));
            continue; // Never connect using the previous credential/config.
        }
        reconnect_count_ = ap_record.direct ? MAX_RECONNECT_COUNT : 0;
        const auto connect_error = esp_wifi_connect();
        if (connect_error == ESP_OK) return;
        ESP_LOGW(TAG, "CONNECT_START_FAILED code=%d", int(connect_error));
    }
    esp_timer_start_once(timer_handle_, scan_current_interval_microseconds_);
    UpdateScanInterval();
}
